<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Document\Template\Application\Service\Visibility\TemplateVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersionRef;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersionAttributes;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionFilter;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionCursor;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionReadGateway;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionSlide;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVersionVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateVersionReadGateway $readGateway,
        private readonly TemplateVersionWriteGateway $writeGateway,
        private readonly TemplateVisibilityService $templateVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(TemplateVersion $content): TemplateVersionAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(TemplateVersion $content): TemplateVersionAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(TemplateVersionAttributes $attributes, ?TemplateVersion $original = null): TemplateVersionAttributes
    {
        $this->logDebug("Copy with fixed for Template version");
        $span = $this->startSpan("Copy with fixed for  Template version");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new TemplateVersionPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(TemplateVersionAttributes $attributes, ?TemplateVersion $original = null): TemplateVersionAttributes
    {
        $this->logDebug("Copy with hidden for Template version");
        $span = $this->startSpan("Copy with hidden for  Template version");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|TemplateVersionRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Template version");
        $span = $this->startSpan("Check visibility of an iterator for  Template version");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new TemplateVersionRef($value));
            } elseif ($value instanceof TemplateVersionRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new TemplateVersionFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(TemplateVersionFilter $filter, ?TemplateVersionCursor $cursor = null): TemplateVersionSlide
    {
        $this->logDebug("List visibles for Template version");
        $span = $this->startSpan("List visibles for  Template version");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (TemplateVersion $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(TemplateVersionFilter $filter): int
    {
        $this->logDebug("Count visibles for Template version");
        $span = $this->startSpan("Count visibles for  Template version");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(TemplateVersionFilter $filter, ?TemplateVersionCursor $cursor = null): TemplateVersionSlide
    {
        $this->logDebug("List visibles for update for Template version");
        $span = $this->startSpan("List visibles for update for  Template version");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (TemplateVersion $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(TemplateVersionFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Template version");
        $span = $this->startSpan("Count visibles for update for  Template version");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(TemplateVersionRef $ref): ?TemplateVersion
    {
        $this->logDebug("Retrieve visible for Template version");
        $span = $this->startSpan("Retrieve visible for  Template version");
        try {
            $filter = new TemplateVersionFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(TemplateVersionRef $ref): ?TemplateVersion
    {
        $this->logDebug("Retrieve visible for update for Template version");
        $span = $this->startSpan("Retrieve visible for update for  Template version");
        try {
            $filter = new TemplateVersionFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?TemplateVersionRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Template version");
        $span = $this->startSpan("Check fields for fix for Template version");
        try {
            $result = $this->dispatcher->dispatch(new TemplateVersionCollectNonEditableFields(TemplateVersion::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?TemplateVersionRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Template version");
        $span = $this->startSpan("Check fields to hide for  Template version");
        try {
            $result = $this->dispatcher->dispatch(new TemplateVersionCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(TemplateVersionAttributes $attributes): TemplateVersionAttributes
    {
        $this->logDebug("Check visibility of parent references for Template version");
        $span = $this->startSpan("Check visibility of parent references for  Template version");
        try {
            $template = $attributes->getTemplate();
            if (null !== $template && !$this->templateVisibilityService->checkVisibility($template)) {
                throw new NotFoundException("Unknown Template " . ($template->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(TemplateVersionFilter $filter): TemplateVersionFilter
    {
        $this->logDebug("Compose visibility filter for Template version");
        $span = $this->startSpan("Compose visibility filter for  Template version");
        try {
            $result = $this->dispatcher->dispatch(new TemplateVersionRestrictFilterToVisibility($filter));
            return $result->templateVersionFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(TemplateVersion $value): bool
    {
        $this->logDebug("Check if item is visible for Template version");
        $span = $this->startSpan("Check if item is visible for  Template version");
        try {
            $result = $this->dispatcher->dispatch(new TemplateVersionVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(TemplateVersion $content, bool $inlist): TemplateVersionAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Template version");
        $span = $this->startSpan("Prepare hydration to visible data for Template version");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new TemplateVersionEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
